import json
from pathlib import Path
base=Path('docs/quality/summary-qa/oath-chronicles-of-empire-and-exile/2026-11-05-batch-002957/seed-iteration-13')
qdoc=json.loads((base/'questions.json').read_text())
s=(base/'summary-snapshot.md').read_text()

def from_to(start, end=None):
    i=s.index(start)
    j=s.index(end,i) if end else len(s)
    return s[i:j].rstrip()
def heading(title, level='###'):
    marker=f'{level} {title}'
    i=s.index(marker)
    j=s.find('\n'+level+' ',i+len(marker))
    return s[i:(j if j>=0 else len(s))].rstrip()
def exact(*parts):
    out='\n\n'.join(p.rstrip() for p in parts)
    assert out in s, 'combined exact passages should be present verbatim'
    return out

def oath(): return heading('Oathkeeper title and four Oaths')
def timing(): return heading('Title transfer and victory timing')
def wake(): return heading('Wake: mandatory order')
def rest(): return heading('Rest: mandatory order')
def search(): return heading('Search — 2–4 Supply')
def muster(): return heading('Muster — 1 Supply')
def trade(): return heading('Trade — 1 Supply')
def recover(): return heading('Recover — 1 Supply plus target cost')
def campaign(): return heading('Campaign — 2 Supply')
def travel(): return heading('Travel — 1–4 Supply before modifiers')
def citizen(): return heading('Citizenship and exile during play')
def chronicle(): return heading('Writing the Chronicle (Law §8, with base errata)')
def visions():
    v=heading('Title transfer and victory timing')
    i=v.index('**Visionary victory:**')
    j=v.index('\n\n**Stable regime:**',i)
    return v[i:j]
def stable():
    v=heading('Title transfer and victory timing')
    i=v.index('**Stable regime:**')
    j=v.index('\n\n**War exhaustion:**',i)
    return v[i:j]
def war():
    v=heading('Title transfer and victory timing')
    return v[v.index('**War exhaustion:**'):]
def successor():
    v=heading("Citizen succession is a separate test")
    return v

def code(p): return '```text\n'+p+'\n```'

def ans(p, application):
    assert p and p in s
    return code(p)+'\n\n'+application

campaign_full=campaign()
qs={
'Q001':(exact(wake(),timing()),'If an Exile takes the title during Act, the next time their Wake comes around, step 2 checks victory while the title is still Oathkeeper-side; step 3 then flips it to Usurper. They can first win at the following Wake check, unless the end of round 8 arrives first while they still hold it Usurper-side. If another player takes the title before that win, they cannot win as Usurper; retaking it resets the title to Oathkeeper-side and restarts this sequence.'),
'Q002':(exact(oath(),visions()),'The four pairings are: Supremacy–Conquest, People–Rebellion, Protection–Sanctuary, Devotion–Faith, each matching its displayed Oath criterion. A Visionary also needs at least 3 world-deck Visions drawn by all players combined. For Conquest/Sanctuary “most” is strictly more than every other player, so a tie for most does not qualify.'),
'Q003':(exact(from_to('## Turn Structure','## Actions'),stable()),'After everyone has taken a turn, check round-end victory; the end die is rolled at the ends of rounds 5, 6, and 7 only if the Chancellor or a Citizen is Oathkeeper. Results 6 in round 5, 5–6 in round 6, and 3–6 in round 7 end the game. An Exile Oathkeeper or Usurper prevents the roll.'),
'Q004':(exact(war(),successor()),'At the end of round 8, follow the four listed checks in order. Resolve a qualifying Citizen Successor whenever the Chancellor would otherwise win in priorities 1 or 4; this replaces the Chancellor, and the Citizen wins alone. Simultaneous qualifying Exile Visions use Conquest, then Rebellion, then Sanctuary, then Faith.'),
'Q005':(successor(),'The Successor goals are: Supremacy—more combined relics and banners than the Chancellor and every other Citizen; People—hold Darkest Secret; Protection—hold People’s Favor; Devotion—hold Grand Scepter. A Citizen cannot win by revealing a Vision or becoming Usurper. Even meeting the Successor goal alone does not end the game; it matters when the Chancellor would win.'),
'Q006':(wake(),'At Wake, if you hold People’s Favor, choose to add one favor from your board or return one favor from the banner to a least-full suit bank (choosing among ties). Never remove its last favor; at one, add if able, and if unable do nothing. If it is already Mob-side, repeat the choice once. Then, if it has at least six favor, flip it to Mob. If it flips at this last check, it does not get an extra payment that Wake.'),
'Q007':(rest(),'Rest in this order: return favor from denizens/edifices to matching suit banks; return secrets from denizens/edifices/relics to your board and flip your facedown board secrets faceup; refresh Supply (Chancellor/Exile by warbands left in personal bank, Citizen to the exact Chancellor marker space); save each unspent Supply by moving one extra space left per point, capped at the leftmost space (7 Supply); then use optional Rest powers, once each in chosen order. The summary specifies Chancellor refresh bands as 6/5/4/3 for 18+/11–17/4–10/0–3 warbands, and Exile bands as 6/5/4 for 9+/4–8/0–3. A Citizen tracks the Chancellor marker exactly, including leftmost; do not count purple warbands.'),
'Q008':(search(),'Search chooses either the world deck or the discard pile for the pawn’s region. Discard pile costs 2 Supply; world deck costs 2 at zero Visions drawn, 3 at 1–2, or 4 at 3–5, reduced to 2 by Darkest Secret (other modifiers still apply). Draw three unless source runs out, a world-deck Vision stops the draw, or a modifier reduces it; do not stop voluntarily. World deck: draw one at a time, announce a Vision (not necessarily its identity), stop and advance the track. Discard pile: a Vision neither stops drawing nor advances the track. If the chosen source empties, draw what remains; no reshuffle. Discard all but one before playing, or discard the last too.'),
'Q009':(exact(heading('Search — 2–4 Supply').split('**Discard destinations:**')[1].split('\n\nAdviser retention')[0].join(['**Discard destinations:**','']) if False else heading('Search — 2–4 Supply')[heading('Search — 2–4 Supply').index('**Discard destinations:**'):heading('Search — 2–4 Supply').index('\n\nAdviser retention')]),'Discards go facedown on the next region’s pile in the Cradle → Provinces → Hinterland → Cradle cycle. Cards from hand/advisers use the destination based on your pawn’s region; never use that same-region pile. If discarding a card at a site in another region, use that card’s region for the cycle. Favor on a discarded card returns immediately to its matching bank; secrets go facedown to the acting player’s board. Thus a remote-site discard follows the remote card’s region, not your pawn’s region.'),
'Q010':(exact(heading('Search — 2–4 Supply').split('\n\n**Discard destinations:**')[0],heading('Search — 2–4 Supply')[heading('Search — 2–4 Supply').index('Adviser retention depends'):heading('Search — 2–4 Supply').index('\n\n**Conspiracy:**')]),'Advisers are limited to three total, faceup and facedown. Facedown advisers have no suit, restriction banner, or power; any card, including a site-only card or Vision, may be held facedown. Later, a facedown adviser may be peeked at, played faceup to a legal destination, or discarded by minor action. A faceup adviser cannot be discarded at will, only when a rule permits or requires it (subject to locks). Exiles may reveal a true Vision in their separate Revealed Vision slot, replacing and discarding their old revealed Vision; it is not an adviser. Chancellor/Citizens can hold true Visions facedown but cannot reveal them.'),
'Q011':(exact(muster(),trade()),'Muster costs 1 Supply: put one favor on an empty denizen or intact edifice at your pawn’s site and gain two warbands from personal bank to board (purple for a Citizen); the card must have no favor or secrets. Relics and ruins are ineligible; site rule is unnecessary, but remote rule does not allow remote Muster. Trade also costs 1 Supply and uses an empty denizen/intact edifice at your pawn’s site (not a relic or ruin). Pay one secret to gain one favor plus one per matching faceup adviser from that card’s suit bank, or pay two favor to gain one shared-bank secret per matching faceup adviser. Facedown advisers do not match; with none matching, the second trade gives zero secrets, but the two-favor cost remains payable. Limited favor/warband sources yield only what is available; secrets are unlimited.'),
'Q012':(recover(),'To Recover, spend 1 Supply plus the target cost. A relic must be facedown at your site; pay its printed site Recover cost, then hold it faceup in your personal bank. Either banner may be recovered from anywhere, including yourself or shared bank, by paying a quantity strictly greater than its current resources. For People’s Favor, place the new payment on the banner and distribute old favor one at a time to suit banks, starting wherever chosen and following the printed bank order around; do not return it to the previous holder, and flip Mob to normal. For Darkest Secret, the new holder takes one old secret and the previous holder takes the rest; if recovering from yourself all old secrets return to you, and from shared bank the remainder stays there. No seizure penalty applies to Recover.'),
'Q013':(recover(),'To recover another player’s Darkest Secret, there must be at least one suited card at the holder’s pawn site whose suit matches none of that holder’s faceup advisers. One such unmatched card is enough even if other site cards match. If the holder has no faceup advisers, a suited site card makes the Secret recoverable. An empty site or a ruin-only site protects it because neither has a suited card. Ruins and facedown advisers have no suit. Recovery from yourself or the shared bank ignores this protection.'),
'Q014':(campaign_full,'A legal defender is another player who rules your site or whose pawn is there; if no player rules your site, you may instead choose bandits. At least one target must be at your pawn’s site, and if the defender rules that site you must target it. You may add any defender sites anywhere on the map, one defense die each. If the defender’s pawn is at your site, you may target their relics (printed dice), banners (dice equal to resources on them), or pawn and favor together (two dice). A relic at your site counts as the required local target. Narrow Pass and Hidden Place conditions still apply as described in the special rules.'),
'Q015':(campaign_full,'The attacker chooses up to one attack die per warband in their attacking force. The defense pool is shields rolled (double symbols multiply shields only), plus defending warbands at targeted sites and the defender’s board force when their pawn is at the attacker’s site or any target; bandit sites add one each. Each attack skull immediately kills one of the attacker’s force warbands. Count full swords and one additional sword per pair of hollow swords; a leftover hollow sword adds none. The attacker may sacrifice surviving force warbands for +1 attack each, but must sacrifice exactly enough to win, never excess. Attack must strictly exceed defense; a tie or lower loses. On victory, defender kills half their defending force rounded down; on defeat, attacker kills half their remaining attacking force rounded down. The full passage also specifies modifiers, battle plans, target resolution and cleanup.'),
'Q016':(campaign_full,'After attacker victory, first resolve the defender’s half-force casualties (rounded down) and battle-plan defeat effects. Then the attacker may place any number of surviving force warbands, including zero, on targeted sites; with zero, a site is left to bandits unless another power applies. Take all targeted relics and banners. A seized banner taken other than by Recover loses two resources down to a minimum of one; People’s Favor flips to Mob. If pawn and favor were targeted, the attacker may force the defender to Travel to a legal chosen site for no Supply and may independently burn half their board favor rounded down. A Shrouded Wood enemy ruler can override the destination choice. Resolve attacker victory effects after targets, then end-discard battle plans; Supremacy title transfers at Campaign end. These steps and Imperial-casualty exceptions are included in the quoted full procedure.'),
'Q017':(campaign_full,'If an Imperial player defends, the Chancellor automatically joins as Ally; other non-attacking Citizens may join with permission if their pawn is at the attacker site or any target. The summary’s full Imperial-defense rules share relevant modifiers and powers across the defending side, share Oathkeeper defense bonus, allow plans at Imperial sites and each user’s own advisers (not others’ advisers), limit a shared plan to one use total by one payer, give the declared defender decision priority when Allies disagree, and specify Chancellor’s choice of Imperial casualties and where survivors go. A Citizen attacking the Chancellor or another Citizen is non-Imperial for that Campaign; a Chancellor attacking a Citizen makes that Citizen non-Imperial. An intra-Empire Campaign does not make all Citizens non-Imperial.'),
'Q018':(exact(travel(),heading('Site powers (Site Reference)').split('- **Coasts:**')[1].split('- **Great Slum:**')[0].join(['- **Coasts:**',''])),'The base costs are: from Cradle to Cradle/Provinces/Hinterland = 1/2/4; from Provinces = 2/2/2; from Hinterland = 4/2/3 Supply. Reveal a facedown destination and stock its printed favor/secrets from the shared bank and printed relic count facedown from the relic deck. Pay fixed-number cost first, then apply other increases/decreases; free Travel is the final override and sets Supply paid to zero even if another power increases it. The cited site rules add: Coast-to-Coast costs 1 and ignores Narrow Pass; travel from Charming Valley adds 1; Shrouded Wood travel from it costs 2 and ignores Narrow Pass/Hidden Place; Narrow Pass requires entry/targeting via it in specified cases. Site-entry restrictions apply unless a power ignores them.'),
'Q019':(citizen(),'During play, the Grand Scepter holder may offer Citizenship to any Exile, including themself, but not on the turn they took the Scepter. The offer must promise exactly one Reliquary relic; it may additionally negotiate binding exchanges of favor, secrets, banners and non-Reliquary relics, and may let the recipient peek at Reliquary relics. If accepted, the recipient flips to Citizen, replaces own board/map warbands with purple (choosing removals if insufficient), discards revealed Vision, flips own Usurper title to Oathkeeper, ends their Act if it is their turn, refreshes to full Supply, and exchanges promised pieces; the Chancellor gains the newly uncovered mandatory Reliquary modifier. Forced Citizenship applies conversion without a negotiated offer, required gift, or invented exchange.'),
'Q020':(chronicle(),'Chronicle procedure: vow the next Oath based on the victory method; offer free Chronicle Citizenship under its distinct rules; build/repair and retain/discard map pieces; repack map slots; add six denizens by adviser-suit allocation (with Dispossessed fallback); dispossess six from discards plus losers’ advisers; handle relics; save the world and board sides; then rebuild the world deck. The top stack is 12 cards because it is 10 denizens plus 2 random Visions. The middle is 18 cards (15 denizens plus the remaining 3 Visions), with remaining denizens below; the Chronicle aid’s “12 denizens + 2” is explicitly incorrect. The quoted full section gives the complete ordered steps and conditions.')
}
